import React, { useState, useEffect, useRef } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in — fyll lungorna', mood:'calm', speed:0.25, distort:0.08 },
  { name:'Håll',      seconds:7, label:'Håll — var stilla',        mood:'default', speed:0.10, distort:0.05 },
  { name:'Andas ut',  seconds:8, label:'Sakta ut — släpp taget',   mood:'flow', speed:0.20, distort:0.08 },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{
      c--; setCount(c);
      if (c<=0){ clearInterval(timer.current); const np=(pi+1)%3; setTimeout(()=>runPhase(np,np===0?ci+1:ci),400); }
    },1000);
  };
  const start = ()=>{ setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current),[]);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 22px', position:'relative' }}>
      <Background mood="flow" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={220} speed={0.7} distort={0.18} />
        </div>
        <h2 style={{ fontSize:34, fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:10 }}>Bra jobbat 🌿</h2>
        <p style={{ fontSize:15, color:'rgba(28,25,23,0.5)', marginBottom:36, fontWeight:300, maxWidth:260, margin:'0 auto 36px' }}>Ditt nervsystem har lugnat ner sig. Alla 4 omgångar klara.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'13px 24px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:13, fontWeight:600, boxShadow:'0 4px 20px rgba(0,0,0,0.18)', border:'none' }}>Checka in humöret</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.65)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.65)', fontSize:13, backdropFilter:'blur(12px)' }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', position:'relative' }}>
      <Background mood={running ? cur.mood : 'default'} />

      <div style={{ flex:1, display:'flex', flexDirection:'column', position:'relative', zIndex:1 }}>
        {/* Phase indicators */}
        <div style={{ padding:'20px 22px 0' }}>
          <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em', marginBottom:12 }}>4 – 7 – 8 andningsövning</p>
          <div style={{ display:'flex', gap:20 }}>
            {PHASES.map((p,i)=>(
              <div key={i}>
                <div style={{ fontSize:20, fontWeight:700, letterSpacing:'-0.03em', color: running&&phase===i ? '#1c1917' : 'rgba(28,25,23,0.2)', transition:'color .5s', lineHeight:1 }}>{p.seconds}</div>
                <div style={{ fontSize:10, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.06em', color: running&&phase===i ? 'rgba(28,25,23,0.55)' : 'rgba(28,25,23,0.18)', transition:'color .5s', marginTop:2 }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Sphere + text — all centered together */}
        <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:0 }}>

          {/* Text above sphere — always centered */}
          <div style={{ textAlign:'center', marginBottom:8, minHeight:52 }}>
            {running ? (
              <>
                <div style={{ fontSize:11, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.1em', color:'rgba(28,25,23,0.4)', marginBottom:4 }}>{cur.name}</div>
                <div style={{ fontSize:52, fontWeight:700, color:'rgba(28,25,23,0.82)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
              </>
            ) : (
              <div style={{ fontSize:11, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.1em', color:'rgba(28,25,23,0.3)' }}>Redo</div>
            )}
          </div>

          {/* Sphere — smooth linear expansion/contraction */}
          <div style={{
            transition: running
              ? phase === 0
                ? `transform ${PHASES[0].seconds}s linear`          // inhale — grows the whole time
              : phase === 1
                ? 'transform 0.8s ease-out'                          // hold — stays large, tiny settle
              : `transform ${PHASES[2].seconds}s linear`            // exhale — shrinks the whole time
              : 'transform 1.4s cubic-bezier(0.16,1,0.3,1)',
            transform: running
              ? phase === 0 ? 'scale(1.32)'                          // end of inhale = large
              : phase === 1 ? 'scale(1.34)'                          // hold = stays large
              : 'scale(0.78)'                                        // end of exhale = small
              : 'scale(1)',
          }}>
            <MeshSphere size={320} speed={running ? cur.speed : 0.3} distort={running ? cur.distort : 0.45} />
          </div>

          {/* Cycle counter below sphere */}
          {running && (
            <div style={{ fontSize:11, color:'rgba(28,25,23,0.3)', marginTop:8, letterSpacing:'0.06em' }}>
              {cycle + 1} / {TOTAL}
            </div>
          )}
        </div>

        {/* Bottom */}
        <div style={{ padding:'0 22px 16px' }}>
          {running ? (
            <div style={{ background:'rgba(255,255,255,0.65)', borderRadius:18, padding:'14px 18px', textAlign:'center', backdropFilter:'blur(16px)', border:'1px solid rgba(255,255,255,0.85)', boxShadow:'0 2px 12px rgba(0,0,0,0.05)' }}>
              <p style={{ fontSize:14, color:'rgba(28,25,23,0.6)', fontWeight:300 }}>{cur.label}</p>
            </div>
          ) : (
            <>
              <h1 style={{ fontSize:'clamp(30px,7vw,48px)', fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:10, lineHeight:1.05 }}>
                Andningsövning<br/><span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.4)' }}>4 minuter</span>
              </h1>
              <p style={{ fontSize:14, color:'rgba(28,25,23,0.5)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
                Aktiverar det parasympatiska nervsystemet. Minskar stresshormoner och sänker pulsen.
              </p>
              <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:14, fontWeight:600, border:'none', boxShadow:'0 4px 20px rgba(0,0,0,0.18)' }}>
                Starta →
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
